-- Etap 9: promocje cenowe na produkty + asortyment zawężony do wizytówek i plakatów.
-- Na świeżej bazie (bez produktów) zmiany katalogu są pomijane — wtedy katalog wstawia seed.

CREATE TABLE promotions (
  id                  INTEGER PRIMARY KEY,
  product_id          INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  percent             INTEGER NOT NULL CHECK (percent BETWEEN 1 AND 90),
  label               TEXT,
  ends_at             TEXT,                    -- NULL = do odwołania
  base_prices_json    TEXT NOT NULL,           -- {"id wariantu": cena przed promocją}
  prev_compare_at_gr  INTEGER,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
  ended_at            TEXT
);
CREATE INDEX idx_promotions_open ON promotions(product_id, ended_at);

-- Kategorie
UPDATE categories SET sort = sort + 10 WHERE slug NOT IN ('wizytowki', 'plakaty') AND sort < 10;

-- Pozostałe produkty znikają ze sklepu (zostają w bazie dla historii zamówień)
UPDATE products SET active = 0 WHERE slug NOT IN ('wizytowki-standard', 'wizytowki-soft-touch', 'projekt-plakatu', 'druk-plakatu');

-- Wizytówki Standard
UPDATE products SET category_id = (SELECT id FROM categories WHERE slug = 'wizytowki'), name = 'Wizytówki Standard', short = 'Kreda matowa 350 g/m², druk dwustronny 4+4, format 85×55 mm.', description = 'Najczęściej zamawiane wizytówki: sztywny papier kredowy 350 g/m², żywe kolory CMYK po obu stronach i równe cięcie. Wgrywasz własny plik PDF — przed drukiem sprawdzamy spady i rozdzielczość, a podgląd wysyłamy do akceptacji.', specs_json = '[["Format","85 × 55 mm (+2 mm spadu)"],["Papier","kreda matowa 350 g/m²"],["Kolorystyka","4+4 CMYK"],["Plik","PDF/X-1a, 300 dpi"]]', active = 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE slug = 'wizytowki-standard';
DELETE FROM product_images WHERE product_id = (SELECT id FROM products WHERE slug = 'wizytowki-standard');

-- Wizytówki Premium Soft Touch
UPDATE products SET category_id = (SELECT id FROM categories WHERE slug = 'wizytowki'), name = 'Wizytówki Premium Soft Touch', short = 'Aksamitna folia soft-touch i lakier UV wybiórczy na logo.', description = 'Wizytówka, którą klient zapamięta w dłoni: folia soft-touch o aksamitnym chwycie i błyszczący lakier UV punktowo na logo. Papier 400 g/m² nie wygina się w portfelu.', specs_json = '[["Format","85 × 55 mm"],["Papier","kreda 400 g/m²"],["Uszlachetnienie","folia soft-touch 2-str., lakier UV 1+0"],["Plik","PDF + osobna warstwa lakieru"]]', active = 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE slug = 'wizytowki-soft-touch';
DELETE FROM product_images WHERE product_id = (SELECT id FROM products WHERE slug = 'wizytowki-soft-touch');

-- Projekt plakatu
UPDATE products SET category_id = (SELECT id FROM categories WHERE slug = 'plakaty'), name = 'Projekt plakatu', short = 'Plakat zaprojektowany przez grafika — od A5 do A0, gotowy do druku i do internetu.', description = 'Opisz wydarzenie, ofertę albo promocję i dołącz logo, a grafik przygotuje plakat w wybranym formacie. Dostajesz dwie propozycje, dwie rundy poprawek i komplet plików: PDF do druku ze spadami oraz wersję do social mediów. Plakat możesz od razu wydrukować u nas — dodaj do koszyka „Druk plakatu” w tym samym formacie.', specs_json = '[["Co dostajesz","2 propozycje i 2 rundy poprawek"],["Pliki","PDF do druku (spad 3 mm, CMYK) + PNG do internetu"],["Termin","pierwsze propozycje w 4 dni robocze"],["Formaty","A5–A0, w pionie lub w poziomie"],["Materiały","logo i teksty wgrywasz w koszyku albo wysyłasz mailem"]]', active = 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE slug = 'projekt-plakatu';
DELETE FROM product_images WHERE product_id = (SELECT id FROM products WHERE slug = 'projekt-plakatu');

-- Druk plakatu A5–A0
UPDATE products SET category_id = (SELECT id FROM categories WHERE slug = 'plakaty'), name = 'Druk plakatu A5–A0', short = 'Kreda satyna 170 g/m², pełny kolor. Od 1 sztuki, wysyłka w tubie.', description = 'Plakaty z Twojego pliku albo z projektu zamówionego u nas. Drukujemy na satynowanej kredzie 170 g/m² — kolory są nasycone, a papier nie odbija światła jak błysk. Plakaty zwijamy do sztywnej tuby kartonowej, więc docierają bez zagięć. Cena dotyczy jednej sztuki; większy nakład ustawisz liczbą w koszyku.', specs_json = '[["Papier","kreda satyna 170 g/m²"],["Druk","4+0 CMYK, jednostronnie"],["Plik","PDF, spad 3 mm; 300 dpi (A5–A3), min. 150 dpi (A2–A0)"],["Pakowanie","tuba kartonowa"],["Dostawa","kurier InPost"]]', active = 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE slug = 'druk-plakatu';
DELETE FROM product_images WHERE product_id = (SELECT id FROM products WHERE slug = 'druk-plakatu');
